function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  if (input.confirm_order !== true) throw new Error('Paper order submission requires an explicit user request and confirm_order=true')
  const body = { symbol: String(input.symbol).trim().toUpperCase(), action: input.action, quantity: Number(input.quantity), profile: input.profile === 'runtime' ? 'runtime' : 'demo', account_id: String(input.account_id || 'paper') }
  if (input.price !== undefined) body.price = Number(input.price)
  if (input.signal_id !== undefined) body.signal_id = String(input.signal_id)
  const response = await fetch(apiOrigin() + '/api/paper/orders', {
    method: 'POST',
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
